-- STEP 6 — Blog posts
-- Backs: /blog/ (listing) and /blog/[slug]/ (individual posts).
-- Per project convention, content the doctor edits later lives in Supabase
-- (admin-panel editable) rather than hardcoded JSX — same pattern as
-- disease_pages. Next.js ISR revalidates hourly (see app/blog/[slug]/page.tsx).

create table if not exists public.blog_posts (
  slug                text primary key,
  title               text not null,
  meta_description    text not null,
  focus_keyword       text not null,
  secondary_keywords  jsonb not null default '[]'::jsonb,
  category            text not null,
  tags                jsonb not null default '[]'::jsonb,
  read_time           text not null,
  published_date      date not null,
  intro               jsonb not null default '[]'::jsonb,
  sections            jsonb not null default '[]'::jsonb,
  final_cta           text not null,
  related_disease_slug text not null,
  related_post_slugs  jsonb not null default '[]'::jsonb,
  is_published        boolean not null default true,
  display_order       integer not null default 0,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create index if not exists blog_posts_published_date_idx on public.blog_posts (is_published, published_date desc);

alter table public.blog_posts enable row level security;

-- Anyone (anon key, used by the website) can read published posts only.
create policy "Public can read published blog posts"
  on public.blog_posts for select
  using (is_published = true);

-- Writes are only allowed via the service_role key (admin panel / server
-- actions), which bypasses RLS by design.

-- Self-contained (create or replace, safe to re-run) so this migration
-- doesn't depend on run order relative to supabase/migrations/0001_*.sql,
-- which also defines this same trigger function.
create or replace function public.set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

create trigger blog_posts_set_updated_at
  before update on public.blog_posts
  for each row execute function public.set_updated_at();

-- ============================================================
-- SEED DATA — mirrors lib/data/blog-posts.ts fallback constant.
-- Generated from that same source file (scripts/gen-blog-posts-sql.ts)
-- so the two never drift apart.
-- ============================================================
insert into public.blog_posts (
  slug, title, meta_description, focus_keyword, secondary_keywords,
  category, tags, read_time, published_date, intro, sections, final_cta,
  related_disease_slug, related_post_slugs, is_published, display_order
) values
(
  $v$can-homeopathy-cure-vitiligo$v$,
  $v$Can Homeopathy Cure Vitiligo? 30 Years of Clinical Experience Gives an Honest Answer$v$,
  $v$Can vitiligo be cured by homeopathy? An honest, evidence-based answer from Dr Anavil Yadav of Yadav Homeo Clinic, Jaipur — based on 30 years of treating vitiligo patients.$v$,
  $v$can homeopathy cure vitiligo$v$,
  $v$["vitiligo homeopathy treatment","leucoderma homeopathy","vitiligo repigmentation homeopathy","safed daag homeopathy treatment"]$v$::jsonb,
  $v$Skin Diseases$v$,
  $v$["vitiligo","leucoderma","skin","homeopathy"]$v$::jsonb,
  $v$7 minutes$v$,
  date $v$2026-08-07$v$,
  $v$["If you have vitiligo — those white patches that appear on the skin and refuse to go away — you have probably heard every promise imaginable. Certain diets that will cure it. Herbal oils. Light therapy. And homeopathy.","You deserve an honest answer. Not a sales pitch. Not a miraculous claim. An honest answer — from a clinic that has been treating vitiligo patients for 30 years.","That is what this article is."]$v$::jsonb,
  $v$[{"heading":"What Is Vitiligo and Why Does It Happen?","paragraphs":["Vitiligo — known in Hindi as safed daag or leucoderma — is a condition in which the melanocytes (the cells responsible for producing skin pigment) are destroyed. The result: depigmented white patches that can appear anywhere on the body.","Why does this happen? Modern medicine understands vitiligo as an autoimmune condition — the immune system, for reasons that are not fully understood, begins attacking its own melanocytes. Genetics, stress, trauma, and environmental factors all appear to play a role. But the precise trigger varies from person to person.","This individual variation is exactly why a cookie-cutter treatment rarely works. And it is exactly why classical homeopathy — which treats the individual, not the diagnosis — has produced results for vitiligo patients that standardised dermatological protocols could not."]},{"heading":"What Conventional Dermatology Offers — and Where It Falls Short","paragraphs":["Let me be fair to conventional medicine first. Dermatologists offer several effective tools: PUVA light therapy, narrow-band UVB, tacrolimus cream, topical steroids, and skin grafting for stable vitiligo. These produce results in a proportion of patients — particularly light therapy, which can stimulate repigmentation in areas that still have dormant melanocytes.","The limitation is this: none of these approaches address why the immune system is attacking melanocytes in the first place. They treat the surface — the visible depigmentation — without correcting the underlying immune dysregulation. This is why many patients find their vitiligo spreads again after stopping treatment, or why it appears in new areas even while existing patches are being treated."]},{"heading":"How Classical Homeopathy Approaches Vitiligo Differently","paragraphs":["In classical homeopathy, vitiligo is not a skin disease. It is a systemic immune condition that is expressing itself through the skin. The white patches are a symptom — not the disease itself.","The constitutional remedy prescribed for a vitiligo patient is not chosen to repigment patches. It is chosen to correct the underlying constitutional susceptibility that caused the immune system to attack melanocytes. This means the prescription is based on the complete individual picture of the patient — their physical constitution, their emotional patterns, their response to stress, their general health history, their family medical history, and specific characteristics of their vitiligo.","Two patients with vitiligo on the same area of the body may receive entirely different remedies — because they are different people with different constitutions. This individualisation is what produces results that generic approaches cannot."]},{"heading":"What We Have Seen in 30 Years — Honest Clinical Observations","paragraphs":["I grew up watching my father, Dr T P Yadav, treat vitiligo patients. I have now been practising alongside him for nearly a decade. Based on our combined experience of hundreds of vitiligo cases, here is what we have consistently observed:"],"list":["Halting of spread: This is the most consistent outcome. The majority of patients who complete 6 to 12 months of constitutional treatment stop developing new patches. For a patient who has been watching their vitiligo spread steadily for years, this alone is enormously meaningful.","Repigmentation: Visible return of pigment to existing patches occurs in approximately 40 to 60 percent of patients who complete a full course of treatment. It begins as small brown dots — pigment islands — appearing within the white area, which gradually coalesce and spread inward.","Near-complete clearance: Seen in a smaller subset — perhaps 15 to 25 percent — particularly those with early-stage vitiligo on the face and trunk who begin treatment early."]},{"heading":"Who Responds Best to Homeopathic Treatment for Vitiligo?","paragraphs":["Based on our clinical experience, the following factors predict better response:"],"list":["Earlier stage: vitiligo of less than 5 to 7 years duration typically responds better","Actively spreading: paradoxically, spreading vitiligo often responds better than old, completely stable patches — because there is more immune activity to work with","Face and trunk patches: these areas tend to repigment more readily than fingertips, lips, bony prominences and genitals","Younger patients: stronger vital force and less entrenched pathology","Otherwise good constitutional health: patients without multiple simultaneous autoimmune conditions tend to respond better"],"note":"Conversely, vitiligo of very long standing (15 to 20+ years), patches on fingertips and lips, and patients with multiple autoimmune conditions have a more guarded prognosis. We will always tell you honestly at the first consultation what we believe is achievable in your specific case."},{"heading":"How Long Does Treatment Take?","paragraphs":["This is the question patients most want to know — and the one that requires the most honest answer.","Vitiligo treatment is not quick. Expect a minimum of 12 months for meaningful repigmentation to occur. Most significant improvement happens in the 6 to 18 month window. Some patients continue treatment for 2 to 3 years and continue improving throughout that period.","The first 3 months are often the hardest — when little seems to be happening visibly, but the immune regulation is quietly beginning to shift. Patience here is not passive — it is part of the treatment."]},{"heading":"Should You Try Homeopathy for Your Vitiligo?","paragraphs":["If your vitiligo is spreading and conventional treatment has not stopped it — yes, a genuine trial of constitutional homeopathic treatment is worth pursuing. If you want to avoid the side effects of long-term steroid application — yes. If you are looking for a treatment approach that addresses the root cause rather than managing the surface — yes.","What you must be clear about: a genuine trial means at minimum 12 months of correctly prescribed, individualised constitutional treatment. Not a few weeks of over-the-counter homeopathic products from a medical store. The prescription must be individualised to you — by an experienced classical homeopath who takes the time to understand your complete case.","At Yadav Homeo Clinic, every vitiligo patient receives a 45 to 60 minute first consultation and a carefully individualised prescription. We see patients in Jaipur and online across India and internationally.","If you would like an honest assessment of whether your case is one we believe can benefit — reach out. We respond to every enquiry personally."]}]$v$::jsonb,
